  ('6deaa603-0ade-58b5-8aa9-37fd68b8ab75', '2027a10d-0203-4000-8000-00000000c0de', '4d08de38-55a5-56c6-a425-ee4b2eb21c3e', null, null, 'hotel', 'Drop luggage at Hotel Uhland', 'Leave bags before check-in. Reception is staffed 07:00–23:00; luggage storage before check-in is not documented.', null, 'accepted', 'needs_checking', 'assumption', false, true, null, null, 10, 'assumption: 10 min at reception', '07:00', '23:00', null, null, null, null, null, '2027-10-02', 2, '{"key":"luggage"}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('dfd2e88c-f942-5861-a6e7-ab61408d5a6a', '2027a10d-0203-4000-8000-00000000c0de', '234ae5f0-a881-515a-9a10-d0920a257984', null, null, 'sight', 'Glockenspiel at Marienplatz', 'The figures of the New City Hall carillon perform daily at 11:00 and 12:00, plus 17:00 from March to October. Free, watched from the square.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Glockenspiel_Neues_Rathaus_Munich.jpg/960px-Glockenspiel_Neues_Rathaus_Munich.jpg', 'accepted', 'ready', 'hard', true, true, '2027-10-02T11:00:00+02:00', '2027-10-02T11:15:00+02:00', 15, 'estimate: show lasts about 12–15 min (travel guides; not stated on muenchen.de)', null, null, null, null, 'Free', 0, 'EUR', '2027-10-02', 3, '{"key":"glock","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Glockenspiel_Neues_Rathaus_Munich.jpg","license":"CC0","attribution":"see Commons file page"},"alternative_show_times":["12:00","17:00","21:00 (Nachtspiel)"]}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('baf76836-ab36-5661-8f56-409c0baf56b3', '2027a10d-0203-4000-8000-00000000c0de', '58a52a69-4892-5557-92e2-a731b8a8d792', null, null, 'sight', 'Frauenkirche & south tower view', 'Munich''s cathedral; the south tower platform gives a view over the old town. Tower: Mon–Sat 10:00–17:00, Sun and holidays 11:30–17:00, last ascent 16:30.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Frauenkirche_Munich_March_2013.JPG/960px-Frauenkirche_Munich_March_2013.JPG', 'accepted', 'ready', 'assumption', false, true, null, null, 45, 'visit style normal: 45 min (stairs + lift, platform, church)', null, null, null, null, 'Tower €7.50 (adults); church free', 7.5, 'EUR', '2027-10-02', 4, '{"key":"frauen","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Frauenkirche_Munich_March_2013.JPG","license":"CC BY-SA 3.0","attribution":"see Commons file page"}}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('85a00382-71b6-5e51-947c-654c6cdfbb38', '2027a10d-0203-4000-8000-00000000c0de', '3f75aa03-146c-5943-bbce-2d3ffdfc2fce', null, null, 'meal', 'Lunch at Weisses Bräuhaus', 'Classic Bavarian tavern of the Schneider Weisse brewery in the Tal. Open daily 09:00–23:30, hot food until 22:30.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Weisses_Brauhaus_19-05-24_1041.jpg/960px-Weisses_Brauhaus_19-05-24_1041.jpg', 'accepted', 'ready', 'preference', false, true, null, null, 75, 'visit style normal: 75 min for a sit-down lunch', null, null, false, 'Optional; tables bookable via OpenTable', null, null, null, '2027-10-02', 5, '{"key":"lunch_wb","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Weisses_Brauhaus_19-05-24_1041.jpg","license":"CC BY-SA 4.0","attribution":"see Commons file page"},"meal":"lunch","recommendation_basis":"local institution, wheat-beer brewery tavern"}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
