  ('4d7aee55-3950-5369-b63c-e2ae130e7514', '2027a10d-0203-4000-8000-00000000c0de', '1d47e7ff-8ae1-5ea7-afcc-c2fe9482beec', null, null, 'museum', 'Residenz München', 'Former royal palace of the Wittelsbachs: Antiquarium, state rooms, Treasury. Summer hours daily 09:00–18:00, last entry 17:00.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Antiquarium,_M%C3%BCnchner_Residenz.jpg/960px-Antiquarium,_M%C3%BCnchner_Residenz.jpg', 'accepted', 'ready', 'assumption', false, true, null, null, 120, 'visit style normal: 2 h for the Residence Museum', null, null, null, null, 'Residence Museum €10 (reduced €9); with Treasury €15', 10, 'EUR', '2027-10-02', 7, '{"key":"res","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Antiquarium,_M%C3%BCnchner_Residenz.jpg","license":"CC0","attribution":"see Commons file page"}}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
