  ('ba6dd54b-c7aa-5f7c-a8fb-ca1b2b940779', '2027a10d-0203-4000-8000-00000000c0de', '21e49603-f2af-5a7d-b7d5-9a36aa488d67', null, null, 'meal', 'Dinner at Augustiner-Keller', 'Traditional Augustiner beer hall and chestnut beer garden between Hbf and Hackerbrücke, ten minutes from the hotel. Beer from wooden barrels.', null, 'accepted', 'ready', 'preference', false, true, null, null, 90, 'visit style normal: 90 min dinner', null, null, true, 'Recommended on a Wiesn Saturday; online booking on the official site', null, null, null, '2027-10-02', 9, '{"key":"dinner_ak","meal":"dinner","recommendation_basis":"muenchen.de restaurant guide; near the hotel"}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('f4ee3607-6852-5c91-a878-79b05ed223f5', '2027a10d-0203-4000-8000-00000000c0de', '4d08de38-55a5-56c6-a425-ee4b2eb21c3e', null, null, 'hotel', 'Breakfast at Hotel Uhland', 'Buffet breakfast, included in the room rate. Served daily 07:30–10:00.', null, 'accepted', 'ready', 'hard', false, true, null, null, 45, 'assumption: 45 min', '07:30', '10:00', null, null, null, null, null, '2027-10-03', 1, '{"key":"breakfast","meal":"breakfast"}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
