  ('4ddfaddf-fdbc-5e72-b353-88075f07e750', '2027a10d-0203-4000-8000-00000000c0de', 'eb39d63b-2d70-5188-a2aa-0deae7e1b77b', null, null, 'event', 'Oktoberfest – last Wiesn day', 'Final day of Oktoberfest 2027. Grounds, tents and rides open at 09:00 (Oide Wiesn 10:00). Go early: tents fill up fast on the last Sunday.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/M%C3%BCnchen_%E2%80%93_Theresienwiese,_Oktoberfest_2015_(Antennen).jpg/960px-M%C3%BCnchen_%E2%80%93_Theresienwiese,_Oktoberfest_2015_(Antennen).jpg', 'accepted', 'ready', 'assumption', false, true, null, null, 135, 'visit style normal: 2 h 15 min walk-around and rides before the Böllerschießen', null, null, null, null, 'Free entry; Oide Wiesn admission extra. Beer 2026: €14.80–15.90 per litre', 0, 'EUR', '2027-10-03', 3, '{"key":"wiesn","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:M%C3%BCnchen_%E2%80%93_Theresienwiese,_Oktoberfest_2015_(Antennen).jpg","license":"CC BY 2.0 de","attribution":"see Commons file page"}}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('a3dfb114-3259-5929-b917-ecb31bb63f29', '2027a10d-0203-4000-8000-00000000c0de', 'acc2598d-6de3-5118-a7f2-c06837619252', null, null, 'event', 'Böllerschießen at the Bavaria', 'Traditional farewell to the Wiesn: about 60 marksmen fire salute shots on the steps below the Bavaria at 12:00, followed by brass music and the Bavarian anthem.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Bavaria_Statue_and_Ruhmeshalle_Munich,_April_2019_-01.jpg/960px-Bavaria_Statue_and_Ruhmeshalle_Munich,_April_2019_-01.jpg', 'accepted', 'ready', 'hard', true, true, '2027-10-03T12:00:00+02:00', '2027-10-03T12:30:00+02:00', 30, 'start 12:00 per oktoberfest.de/muenchen.de; end time not published, 30 min estimated', null, null, null, null, 'Free', 0, 'EUR', '2027-10-03', 4, '{"key":"boeller","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Bavaria_Statue_and_Ruhmeshalle_Munich,_April_2019_-01.jpg","license":"CC BY-SA 4.0","attribution":"see Commons file page"},"fixed_end_estimated":true}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('3dc5b825-5504-5e87-aa24-59e59a3b0d7c', '2027a10d-0203-4000-8000-00000000c0de', 'eb39d63b-2d70-5188-a2aa-0deae7e1b77b', null, null, 'meal', 'Lunch in a Wiesn tent', 'Roast chicken and a Maß in one of the beer tents. Without a reservation, look for unreserved tables or try the smaller tents.', null, 'accepted', 'ready', 'preference', false, true, null, null, 75, 'visit style normal: 75 min', null, null, false, 'Tent reservations for the last weekend are usually gone; unreserved areas exist', null, null, null, '2027-10-03', 5, '{"key":"lunch_wiesn","meal":"lunch"}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('b5365e43-c477-57a4-80ca-d9041da802f4', '2027a10d-0203-4000-8000-00000000c0de', '3aff4315-e6ae-5e8b-bdea-9159bcdaea08', null, null, 'museum', 'Alte Pinakothek', 'Old Masters from the 14th to 18th century (Dürer, Rubens, Raphael). Open on 3 Oct 2027 until 18:00 per muenchen.de; €1 entry on Sundays.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Alte_Pinakothek_M%C3%BCnchen_2008.jpg/960px-Alte_Pinakothek_M%C3%BCnchen_2008.jpg', 'accepted', 'ready', 'assumption', false, true, null, null, 120, 'visit style normal: 2 h', null, null, null, null, '€1 on Sundays (regular price disputed: €9 official, €7 muenchen.de)', 1, 'EUR', '2027-10-03', 6, '{"key":"ap","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Alte_Pinakothek_M%C3%BCnchen_2008.jpg","license":"CC0","attribution":"see Commons file page"}}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('5542bd11-fe45-5509-8a3a-0b8d6d28ce69', '2027a10d-0203-4000-8000-00000000c0de', '056b8005-0d30-5829-99a7-07735be2533c', null, null, 'departure', 'ICE departure from München Hbf', 'Train back to Stuttgart (demo booking). Be on the platform 15 min early.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/(DE)_M%C3%BCnchen_Hauptbahnhof_-_26.04.2014_(14018991320).jpg/960px-(DE)_M%C3%BCnchen_Hauptbahnhof_-_26.04.2014_(14018991320).jpg', 'accepted', 'ready', 'hard', true, true, '2027-10-03T18:32:00+02:00', null, 15, 'assumption: 15 min to find the platform', null, null, null, null, null, null, null, '2027-10-03', 7, '{"key":"departure","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:(DE)_M%C3%BCnchen_Hauptbahnhof_-_26.04.2014_(14018991320).jpg","license":"CC BY 2.0","attribution":"see Commons file page"},"mode":"train","to":"Stuttgart Hbf","demo_booking":true}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
  ('f72514ef-bb37-54a6-b690-6a371a5fc2f4', '2027a10d-0203-4000-8000-00000000c0de', 'b426ddf8-ffcb-58ca-bfcc-5b65b0ea1aec', null, null, 'museum', 'Deutsches Museum', 'One of the world''s largest science and technology museums, on an island in the Isar. Daily 09:00–17:00, last admission 16:30.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Deutsches_Museum_-_exterior.jpg/960px-Deutsches_Museum_-_exterior.jpg', 'accepted', 'ready', 'assumption', false, true, null, null, 150, 'visit style normal: 2.5 h (very large museum; pick a few halls)', null, null, null, null, 'Adults €16 (muenchen.de)', 16, 'EUR', null, null, '{"key":"dm","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Deutsches_Museum_-_exterior.jpg","license":"CC BY-SA 4.0","attribution":"see Commons file page"}}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
