  ('9d88e1cd-a13a-558e-b47a-3914dcb52783', '2027a10d-0203-4000-8000-00000000c0de', '90b6648d-b687-58b2-b463-824cdb5deb0b', null, null, 'nature', 'Englischer Garten & Chinese Tower', 'Walk through the English Garden to the Chinese Tower beer garden (one of the largest in Munich). Park open all year; beer garden weather-dependent.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Biergarten_Chinesischer_Turm_(6028129117).jpg/960px-Biergarten_Chinesischer_Turm_(6028129117).jpg', 'accepted', 'ready', 'assumption', false, true, null, null, 90, 'visit style normal: 90 min walk incl. a drink', null, null, null, null, null, null, null, null, null, '{"key":"eg","image_credit":{"source":"Wikimedia Commons","page":"https://commons.wikimedia.org/wiki/File:Biergarten_Chinesischer_Turm_(6028129117).jpg","license":"CC BY 2.0","attribution":"see Commons file page"}}'::jsonb, '2026-10-07T20:00:00Z', '2026-10-07T20:00:00Z'),
